public class Main {
    int[] finalPrices(int[] prices) {
        int[] result = prices.clone();
        for (int i = 0; i < prices.length; i++) {
            for (int j = i + 1; j < prices.length; j++) {                              // scan forward for the FIRST price <= prices[i]
                if (prices[j] <= prices[i]) {
                    result[i] = prices[i] - prices[j];
                    break;
                }
            }
        }
