    stack = []                                                              # a monotonic NON-DECREASING stack of indices still awaiting their discount
    for i, price in enumerate(prices):
        while stack and prices[stack[-1]] >= price:                        # price is the FIRST later price <= everything waiting on top
            idx = stack.pop()
            result[idx] = prices[idx] - price
        stack.append(i)
    return result                                                           # anything left on the stack never found a discount (unchanged)


