import java.util.*;

public class Main {
    int[] finalPrices(int[] prices) {
        int[] result = prices.clone();
        Deque<Integer> stack = new ArrayDeque<>();                                    // a monotonic NON-DECREASING stack of indices still awaiting their discount
        for (int i = 0; i < prices.length; i++) {
            while (!stack.isEmpty() && prices[stack.peek()] >= prices[i]) {              // prices[i] is the FIRST later price <= everything waiting on top
                int idx = stack.pop();
                result[idx] = prices[idx] - prices[i];
            }
            stack.push(i);
        }
        return result;                                                                   // anything left on the stack never found a discount (unchanged)
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] prices = {8, 4, 6, 2, 3};
        System.out.println(Arrays.toString(solution.finalPrices(prices)));
    }
}

